function fabricView(){const p=state.fabric;const matches=fabrics.map(x=>({...x,score:S.fabricScore(x,p)})).filter(x=>x.score!==null).sort((a,b)=>b.score-a.score);return panel('What does your design need?',fields(f('fabric','construction','Must have: construction','text',['Any','Woven','Knit'])+f('fabric','minGsm','Must have: minimum GSM','number')+f('fabric','maxGsm','Must have: maximum GSM','number')+f('fabric','minStretch','Must have: minimum stretch (%)','number')+f('fabric','drape','Prefer: drape','text',['Any','Crisp','Medium','Fluid','Soft'])+f('fabric','climate','Prefer: climate','text',['Any','Warm','Mild','Cool']))+note('A curated starting library, not a supplier inventory. Values below are representative examples, not guaranteed specifications. Hard filters exclude fabrics; preferences order the remaining examples.'))+panel(matches.length+' fabric options',`${p.minGsm>p.maxGsm?'<p class="error">Minimum GSM cannot exceed maximum GSM. Update the filters above.</p>':''}<div class="cards">${matches.map(x=>`<article class="card"><span class="eyebrow">${x.construction} · ${x.gsm} GSM example</span><h3>${x.name}</h3><p>${x.composition}<br>Width: ${x.width} cm example · Stretch: ${x.stretch}% example<br>${x.drape} drape · ${x.opacity}<br>Uses: ${x.use}</p><p class="note">${x.care}</p><button data-action="chooseFabric" data-id="${x.id}">Add to tech pack BOM</button></article>`).join('')}</div>${matches.length?'':'<p>No example meets all required filters. Broaden the requirements or source a custom fabric.</p>'}`)+panel('Your sample test record',fields(f('fabric','sample','Supplier / sample reference')+f('fabric','shrinkage','Measured shrinkage, stretch & test conditions','textarea')+f('fabric','price','Quoted price per metre (INR)','number'))+note('The quote you enter is used when adding a fabric to the BOM. Edit measured consumption, supplier and colour in the tech pack.'));}
