 return srcLink('market','export research','srcSync')+panel('Destination & product',fields(f('market','country','Destination','text',Object.keys(markets))+f('market','product','Product type','text',PRODUCTS)+f('market','garment','Garment')+f('market','construction','Construction','text',['Knitted','Woven','Not sure'])+f('market','gender','For','text',['Women / girls','Men / boys','Unisex','Babies'])+f('market','hs','HS code — your broker-confirmed code')+f('market','notes','Importer / broker notes','textarea'))+actionBar(button('marketFromPack','Use tech pack details')))
