const PLATFORMS={'Brand website (Shopify, D2C)':{title:70,bullets:5,desc:900,tags:0,note:'Benefit-led title, scannable bullets and a story paragraph; SEO title and meta description included.'},'Amazon':{title:150,bullets:5,desc:2000,tags:0,note:'Title: Brand + gender + product + key feature + material + fit + colour. Five bullets that start with a short capitalised lead. No promotional claims or emojis.'},'Flipkart':{title:100,bullets:5,desc:1500,tags:0,note:'Clear attribute-led title; key features as short bullets.'},'Myntra / Ajio / Nykaa Fashion':{title:80,bullets:5,desc:1000,tags:0,note:'Short title (brand shown separately on most fashion marketplaces); product details, size & fit and material & care sections.'},'Instagram':{title:0,bullets:0,desc:2200,tags:20,note:'Hook in the first line, short lines, a call to action and up to 20 relevant hashtags.'},'Facebook / WhatsApp catalogue':{title:65,bullets:3,desc:600,tags:5,note:'Short and conversational; price and sizes up front.'},'Pinterest':{title:100,bullets:0,desc:500,tags:8,note:'Keyword-rich title and description written for search.'},'Google Shopping feed':{title:150,bullets:0,desc:5000,tags:0,note:'Attribute-first title (brand, gender, product, material, colour, size), plain description, no promotional text.'},'PLM / internal spec':{title:120,bullets:0,desc:3000,tags:0,note:'Neutral, factual spec block for PLM, ERP or a buyer line sheet.'},'Buyer / client line sheet':{title:90,bullets:4,desc:700,tags:0,note:'Professional summary for a wholesale buyer: construction, fabric, sizes, MOQ and delivery.'}};
const TAGS={base:['fashion','style','ootd','outfitoftheday','newarrivals','shopnow','instafashion','fashionstyle'],India:['indianwear','madeinindia','indianfashion','vocalforlocal','ethnicwear','desistyle'],garment:{kurta:['kurta','kurtaset','kurtistyle','ethnicwear','festivewear'],shirt:['shirt','menswear','shirtstyle','workwear','smartcasual'],'t-shirt':['tshirt','tee','graphictee','casualwear','streetwear'],dress:['dress','dresses','summerdress','womenswear','dressup'],trousers:['trousers','pants','tailoring','officewear'],jeans:['jeans','denim','denimstyle','denimlove'],hoodie:['hoodie','streetwear','loungewear','athleisure'],skirt:['skirt','midiskirt','womenswear'],blouse:['blouse','sareeblouse','sareelove','blousedesign'],jacket:['jacket','outerwear','layering'],polo:['poloshirt','polo','smartcasual']},fabric:{cotton:['cotton','purecotton','breathable'],linen:['linen','linenstyle','summerstyle'],silk:['silk','silkstyle','luxury'],denim:['denim'],wool:['wool','winterwear'],khadi:['khadi','handloom','handwoven'],viscose:['viscose','flowy'],rayon:['rayon'],chanderi:['chanderi','handloom']},occasion:{festive:['festivewear','diwalioutfit','festiveseason','celebration'],wedding:['weddingwear','weddingguest','shaadi'],office:['officewear','workwear','9to5style'],everyday:['everydaystyle','casualstyle','comfortwear'],party:['partywear','nightout'],vacation:['vacationstyle','resortwear','travelstyle']},craft:{'block print':['blockprint','handblockprint','artisanmade'],embroidery:['embroidery','handembroidery','embroidered'],'hand embroidery':['handembroidery','artisan'],bandhani:['bandhani','tieanddye'],ikat:['ikat','handwoven'],chikankari:['chikankari','lucknowichikankari'],sustainable:['sustainablefashion','slowfashion','consciousfashion']}};
function copyFacts(){const c=state.copy,g=(c.garment||c.name||'').toLowerCase(),f=(c.fabric||'').toLowerCase();const fit=/\bfit\b/i.test(c.fit)?c.fit:c.fit?c.fit+' fit':'';const features=c.features.split('\n').map(x=>x.trim()).filter(Boolean);return {c,g,f,fit,features,colour:c.colour,gender:c.gender==='Unisex'?'Unisex':c.gender?c.gender+"'s":''};}
function hashtags(n){const {c,g,f,features}=copyFacts(),out=[];const add=a=>a.forEach(t=>{t=t.toLowerCase().replace(/[^a-z0-9]/g,'');if(t&&!out.includes(t))out.push(t);});if(c.brand)add([c.brand]);for(const [k,v] of Object.entries(TAGS.garment))if(g.includes(k))add(v);for(const [k,v] of Object.entries(TAGS.fabric))if(f.includes(k))add(v);for(const [k,v] of Object.entries(TAGS.occasion))if(String(c.occasion).toLowerCase().includes(k))add(v);const all=(features.join(' ')+' '+c.name+' '+c.fabric).toLowerCase();for(const [k,v] of Object.entries(TAGS.craft))if(all.includes(k))add(v);if(c.colour)add([c.colour.split(/[ /,]/)[0]+'outfit']);if(c.market!=='Global')add(TAGS.India);add(TAGS.base);return out.slice(0,n).map(t=>'#'+t);}
