function batchPanel(){const b=BATCH;return panel('Batch: many products at once',note('Upload a CSV with one product per row. Columns: Product, SKU, Brand, Fabric, Fit, Features (separate with ;), Colour, GSM, Sleeve, Neck, Sizes, Occasion, Care. Each row uses the platform, language and tone chosen above. Facts come only from your file.')+actionBar(`<label class="button primary">Upload products CSV<input type="file" data-import="copybatch" accept=".csv,.tsv,.txt,text/csv" hidden></label>`+button('batchTemplate','Download template'))+(b?`<p class="note">${b.rows.length} products · ${escape(b.platform)} · ${escape(b.language)}</p>`+table(['Product','SKU','Draft',''],b.rows.slice(0,200).map(r=>[escape(r.name),escape(r.sku),r.draft?`<small>${escape(r.draft.slice(0,160))}${r.draft.length>160?'…':''}</small>`:`<small class="error">${escape(r.err)}</small>`,r.draft?'✓':'✗']))+actionBar(button('batchCSV','Download all (CSV)',true)):''));}
