 const titleParts={'Amazon':[c.brand,gender,name,features[0],fab,fit,colour],'Google Shopping feed':[c.brand,gender,name,fab,colour,c.sizes?'Sizes '+c.sizes:''],'Flipkart':[c.brand,gender,fab,name,colour],'Myntra / Ajio / Nykaa Fashion':[gender,fab,name,colour?'in '+colour:''],'PLM / internal spec':[c.sku,c.brand,name,colour],'Buyer / client line sheet':[c.sku,name,fab,colour]}[c.platform]||[c.brand,name,colour?'in '+colour:'',fab?'· '+fab:''];
