const FIBRE_T={cotton:{fr:'coton',de:'Baumwolle',es:'algodón',it:'cotone',nl:'katoen',pt:'algodão',ar:'قطن',ja:'綿'},polyester:{fr:'polyester',de:'Polyester',es:'poliéster',it:'poliestere',nl:'polyester',pt:'poliéster',ar:'بوليستر',ja:'ポリエステル'},elastane:{fr:'élasthanne',de:'Elasthan',es:'elastano',it:'elastan',nl:'elastaan',pt:'elastano',ar:'إيلاستين',ja:'ポリウレタン'},spandex:{fr:'élasthanne',de:'Elasthan',es:'elastano',it:'elastan',nl:'elastaan',pt:'elastano',ar:'إيلاستين',ja:'ポリウレタン'},viscose:{fr:'viscose',de:'Viskose',es:'viscosa',it:'viscosa',nl:'viscose',pt:'viscose',ar:'فيسكوز',ja:'レーヨン'},rayon:{fr:'viscose',de:'Viskose',es:'viscosa',it:'viscosa',nl:'viscose',pt:'viscose',ar:'رايون',ja:'レーヨン'},linen:{fr:'lin',de:'Leinen',es:'lino',it:'lino',nl:'linnen',pt:'linho',ar:'كتان',ja:'麻（亜麻）'},wool:{fr:'laine',de:'Wolle',es:'lana',it:'lana',nl:'wol',pt:'lã',ar:'صوف',ja:'毛'},silk:{fr:'soie',de:'Seide',es:'seda',it:'seta',nl:'zijde',pt:'seda',ar:'حرير',ja:'絹'},polyamide:{fr:'polyamide',de:'Polyamid',es:'poliamida',it:'poliammide',nl:'polyamide',pt:'poliamida',ar:'بولي أميد',ja:'ナイロン'},nylon:{fr:'polyamide',de:'Polyamid',es:'poliamida',it:'poliammide',nl:'polyamide',pt:'poliamida',ar:'نايلون',ja:'ナイロン'},acrylic:{fr:'acrylique',de:'Polyacryl',es:'acrílico',it:'acrilica',nl:'acryl',pt:'acrílico',ar:'أكريليك',ja:'アクリル'},modal:{fr:'modal',de:'Modal',es:'modal',it:'modal',nl:'modal',pt:'modal',ar:'مودال',ja:'レーヨン（モダール）'},lyocell:{fr:'lyocell',de:'Lyocell',es:'lyocell',it:'lyocell',nl:'lyocell',pt:'liocel',ar:'ليوسيل',ja:'レーヨン（リヨセル）'}};
const ORIGIN_T={fr:'Fabriqué en',de:'Hergestellt in',es:'Hecho en',it:'Prodotto in',nl:'Gemaakt in',pt:'Fabricado em',ar:'صنع في',ja:'原産国'};
const CARE_MARKETS={'India':{langs:['en'],rules:['Legal Metrology (Packaged Commodities) Rules: on the label or pack, give the manufacturer, packer or importer name and address, country of origin, common or generic name, size, net quantity (number of pieces), month and year of manufacture, MRP inclusive of all taxes, and a consumer care contact.','Fibre content and care instructions are expected by buyers and marketplaces; state fibre percentages with generic names.'],links:[['Legal Metrology (Packaged Commodities) Rules, Department of Consumer Affairs','https://consumeraffairs.nic.in/organisation-and-units/division/legal-metrology/acts-and-rules']],fields:['mrp','mfgDate']},
'United States':{langs:['en'],rules:['Textile Fiber Products Identification Act: fibre content by generic name and percentage by weight, in order of predominance; fibres under 5% may be shown as “other fiber”.','Country of origin (“Made in India”) and the identity of the manufacturer or dealer: company name or an FTC Registered Identification Number (RN).','Care Labeling Rule: permanent label with at least one safe care method, with a reasonable basis; symbols (ASTM D5489) may replace words.'],links:[['FTC: Threading your way through the labeling requirements','https://www.ftc.gov/business-guidance/resources/threading-your-way-through-labeling-requirements-under-textile-wool-acts'],['FTC: Clothes captioning, complying with the Care Labeling Rule','https://www.ftc.gov/business-guidance/resources/clothes-captioning-complying-care-labeling-rule']],fields:['rn']},
'Canada':{langs:['en','fr'],rules:['Textile Labelling Act: fibre content in English and French, with generic names and percentages, plus the dealer’s full name and address or a CA identification number.','Care labelling is voluntary; if used, symbols follow CAN/CGSB-86.1.'],links:[['Competition Bureau: Guide to the Textile Labelling and Advertising Regulations','https://competition-bureau.canada.ca/textile-labelling-and-advertising-regulations-guide']],fields:['rn']},
'United Kingdom':{langs:['en'],rules:['Textile Products (Labelling and Fibre Composition) Regulations 2012: fibre names and percentages in English, with “Contains non-textile parts of animal origin” where it applies.','Care labelling is voluntary but expected by retailers; product safety and origin rules apply separately.'],links:[['GOV.UK: Textile labelling','https://www.gov.uk/guidance/textile-labelling']],fields:[]},
'European Union':{langs:['en','fr','de','es','it'],rules:['Regulation (EU) No 1007/2011: fibre names from the regulation’s list with percentages, in the official language(s) of the member state where the product is sold; “Contains non-textile parts of animal origin” where it applies.','Care symbols are voluntary in law; the ISO 3758 symbols are registered trademarks of GINETEX in many countries, so check licensing before using them.'],links:[['Your Europe: Textile labels','https://europa.eu/youreurope/business/product-requirements/labels-markings/textile-label/index_en.htm']],fields:[]},
'Australia / New Zealand':{langs:['en'],rules:['Consumer goods (care labelling) information standard: permanent care instructions in English on clothing and many textiles.','Country of origin claims must not mislead; fibre content is expected by retailers.'],links:[['Product Safety Australia: Care labelling for clothing and textiles','https://www.productsafety.gov.au/standards/care-labelling-for-clothing-and-textile-products']],fields:[]},
'Japan':{langs:['en','ja'],rules:['Household Goods Quality Labeling Act: fibre composition with the designated Japanese names, care symbols under JIS L 0001, and the labeller’s name and address or telephone number, in Japanese.'],links:[['Consumer Affairs Agency: Household Goods Quality Labeling Act','https://www.caa.go.jp/policies/policy/representation/household_goods/']],fields:[]},
'UAE / Gulf (GCC)':{langs:['en','ar'],rules:['Arabic labelling is generally expected for consumer goods in GCC countries, with country of origin and fibre content; confirm the current GSO and national requirements with your importer.'],links:[['GSO: Gulf Standardization Organization','https://www.gso.org.sa/en/']],fields:[]}};
const LANG_NAMES={en:'English',fr:'French',de:'German',es:'Spanish',it:'Italian',nl:'Dutch',pt:'Portuguese',ar:'Arabic',ja:'Japanese'};
const LABEL_MATS=[['Satin (polyester)','satin','Soft, smooth; common for neck and side-seam labels'],['Woven damask','twill','High-definition woven text; durable'],['Printed cotton tape','poplin','Natural, soft; good for kidswear and organic lines'],['Nylon taffeta','silk','Thin and strong; holds print through many washes'],['Tagless heat transfer','jersey','Printed straight onto the garment; no label to scratch']];
function fibreLine(c,lang){if(lang==='en')return S.label(c);return S.composition(c).map(r=>{const k=r.name.toLowerCase().trim().split(/\s+/).pop(),t=(FIBRE_T[k]||{})[lang];return r.percent+'% '+(t||r.name);}).join(', ');}
function careLangs(){const c=state.care,m=CARE_MARKETS[c.market]||CARE_MARKETS.India;return c.langs?c.langs.split(',').filter(x=>LANG_NAMES[x]):m.langs;}
function careText(){const c=state.care,lines=[c.brand,'Size '+c.size],langs=careLangs();lines.push('Shell: '+langs.map(l=>fibreLine(c.shell,l)).join(' / '));if(c.lining.trim())lines.push('Lining: '+langs.map(l=>fibreLine(c.lining,l)).join(' / '));for(const k of Object.keys(careOptions)){if(c[k]==='Select approved instruction')throw Error('Choose all care steps based on approved tests.');lines.push([c[k],...langs.filter(l=>CARE_T[l]).map(l=>CARE_T[l][c[k]]||'')].filter(Boolean).join(' / '));}if(!c.evidence.trim())throw Error('Record the approved care test / supplier evidence reference.');if(c.origin.trim())lines.push(['Made in '+c.origin,...langs.filter(l=>ORIGIN_T[l]).map(l=>l==='ja'?ORIGIN_T[l]+'：'+c.origin:ORIGIN_T[l]+' '+c.origin)].join(' / '));if(c.rn.trim())lines.push(c.rn);if(c.contact.trim())lines.push(c.contact);if(c.market==='India'){if(c.mfgDate)lines.push('Mfd: '+c.mfgDate);if(c.mrp>0)lines.push('MRP ₹'+c.mrp+' (incl. of all taxes)');}if(c.extra.trim())lines.push(c.extra);return lines.filter(Boolean).join('\n');}
function careSym(k,v){const s='stroke="#111" stroke-width="1.4" fill="none"',x='<path d="M3 3 L21 21 M21 3 L3 21" stroke="#111" stroke-width="1.4"/>';if(k==='wash'){if(/Do not/.test(v))return `<path d="M3 7 L5 19 H19 L21 7" ${s}/><path d="M3 7 Q7 4 12 7 T21 7" ${s}/>${x}`;if(/Hand/.test(v))return `<path d="M3 7 L5 19 H19 L21 7" ${s}/><path d="M3 7 Q7 4 12 7 T21 7" ${s}/><path d="M9 11 v-4 M11 11 v-5 M13 11 v-5 M15 11.5 v-3" ${s}/>`;const t=(/(\d+)°C/.exec(v)||[])[1];const dots={30:1,40:2,60:3}[t]||1;return `<path d="M3 7 L5 19 H19 L21 7" ${s}/><path d="M3 7 Q7 4 12 7 T21 7" ${s}/>`+(t?`<text x="12" y="16.5" font-size="7" text-anchor="middle" font-family="Arial" font-weight="700">${t}</text>`:Array.from({length:dots},(_,i)=>`<circle cx="${12+(i-(dots-1)/2)*3.5}" cy="13.5" r="1" fill="#111"/>`).join(''))+(/gentle/.test(v)?'<path d="M5 22 H19" stroke="#111" stroke-width="1.2"/>':'');}
 if(k==='bleach'){const tri=`<path d="M12 3 L21 19 H3 Z" ${s}/>`;if(/Do not/.test(v))return tri+x;if(/non-chlorine/.test(v))return tri+'<path d="M10 17 L14 9 M13 17 L16.5 10.5" stroke="#111" stroke-width="1.2"/>';return tri;}
 if(k==='dry'){const sq=`<rect x="3" y="3" width="18" height="18" ${s}/>`;if(/Tumble/.test(v)){const c2=`<circle cx="12" cy="12" r="6" ${s}/>`;if(/Do not/.test(v))return sq+c2+x;return sq+c2+(/low/.test(v)?'<circle cx="12" cy="12" r="1" fill="#111"/>':'<circle cx="10.5" cy="12" r="1" fill="#111"/><circle cx="13.5" cy="12" r="1" fill="#111"/>');}if(/flat/.test(v))return sq+'<path d="M6 12 H18" stroke="#111" stroke-width="1.4"/>';if(/Drip/.test(v))return sq+'<path d="M9 6 V18 M12 6 V18 M15 6 V18" stroke="#111" stroke-width="1.2"/>';return sq+'<path d="M12 6 V18" stroke="#111" stroke-width="1.4"/>'+(/shade/.test(v)?'<path d="M3 9 L9 3" stroke="#111" stroke-width="1.2"/>':'');}
 if(k==='iron'){const ir=`<path d="M4 18 H21 V15 Q21 8 14 8 H8 Q5 8 4 18 Z" ${s}/><path d="M9 8 V6 H17" ${s}/>`;if(/Do not/.test(v))return ir+x;const d={low:1,medium:2,high:3}[(/(low|medium|high)/.exec(v)||[])[1]]||1;return ir+Array.from({length:d},(_,i)=>`<circle cx="${13+(i-(d-1)/2)*3}" cy="14" r="1" fill="#111"/>`).join('');}
 if(k==='professional'){const c2=`<circle cx="12" cy="12" r="8.5" ${s}/>`;if(/Do not/.test(v))return c2+x;return c2+`<text x="12" y="15.5" font-size="9" text-anchor="middle" font-family="Arial">${/wet/.test(v)?'W':'P'}</text>`;}return '';}
function careLabelHTML(){const c=state.care,mat=LABEL_MATS.find(m=>m[0]===c.material)||LABEL_MATS[0],sc=3.2,w=Math.min(120,Math.max(15,c.width)),h=Math.min(200,Math.max(20,c.height));let text='',err='';try{text=careText();}catch(e){err=e.message;text=careTextDraft();}
 const bg=c.labelColour==='Black'?'#1d1d1f':c.labelColour==='Ivory'?'#f3ecd9':c.labelColour==='Navy'?'#1f2a44':'#fbfbf8',ink=['Black','Navy'].includes(c.labelColour)?'#f2f2f2':'#111';
 const lines=text.split('\n'),sym=c.symbols?Object.keys(careOptions).filter(k=>c[k]!=='Select approved instruction').map(k=>`<svg viewBox="0 0 24 24" width="${(6*sc).toFixed(0)}" height="${(6*sc).toFixed(0)}" style="filter:${ink==='#111'?'none':'invert(1)'}">${careSym(k,c[k])}</svg>`).join(''):'';
 const fold=c.fold==='End fold'?'<i class="cl-fold t"></i><i class="cl-fold b"></i>':c.fold==='Centre fold'?'<i class="cl-fold m"></i>':'';
 const fs=Math.max(5.5,Math.min(9,(h*sc-(c.symbols?40:20))/(lines.length*1.55+(lines.join(' ').length/(w*0.55))*1.2)));
 return `<div class="cl-wrap" id="clLive"><div class="cl-label ${c.fold==='Centre fold'?'cf':''}" data-tex="${mat[1]}" style="width:${w*sc}px;min-height:${h*sc}px;background-color:${bg};color:${ink};font-size:${fs.toFixed(1)}px">${fold}<div class="cl-in">${c.logo?`<b class="cl-brand">${escape(c.brand)}</b>`:''}${lines.filter((l,i)=>!(c.logo&&i===0)).map(l=>`<p>${escape(l)}</p>`).join('')}${sym?`<div class="cl-sym">${sym}</div>`:''}</div></div><p class="note">${escape(mat[0])} · ${escape(c.labelColour)} · ${w} × ${h} mm · ${escape(c.fold)}. ${escape(mat[2])}.</p>${err?`<p class="error">${escape(err)}</p>`:''}</div>`;}
function careTextDraft(){const c=state.care;const L=[c.brand,'Size '+c.size];try{L.push('Shell: '+S.label(c.shell));}catch(e){L.push('Shell: '+c.shell.replace(/\n/g,', '));}if(c.lining.trim())L.push('Lining: '+c.lining.replace(/\n/g,', '));Object.keys(careOptions).forEach(k=>{if(c[k]!=='Select approved instruction')L.push(c[k]);});if(c.origin)L.push('Made in '+c.origin);return L.filter(Boolean).join('\n');}
function paintLabels(){if(!window.ForecutFabricPreview)return;document.querySelectorAll('.cl-label[data-tex]').forEach(el=>{const c=document.createElement('canvas');c.width=240;c.height=240;const bg=getComputedStyle(el).backgroundColor,m=/(\d+),\s*(\d+),\s*(\d+)/.exec(bg)||[0,250,250,248],hex='#'+[1,2,3].map(i=>(+m[i]).toString(16).padStart(2,'0')).join('');ForecutFabricPreview.draw(c,hex,el.dataset.tex);el.style.backgroundImage='url('+c.toDataURL()+')';});}
function updateCare(){if(tool!=='care-label-generator')return;const w=$('#clLive');if(w){const t=document.createElement('div');t.innerHTML=careLabelHTML();w.replaceWith(t.firstElementChild);paintLabels();}}
function careView(){const c=state.care,m=CARE_MARKETS[c.market]||CARE_MARKETS.India,langs=careLangs();
 return panel('Destination & label',fields(f('care','market','Selling in','text',Object.keys(CARE_MARKETS))+`<label>Label languages<span class="cl-langs">${Object.keys(LANG_NAMES).map(l=>`<label class="cl-lang"><input type="checkbox" data-carelang="${l}" ${langs.includes(l)?'checked':''}>${LANG_NAMES[l]}</label>`).join('')}</span></label>`)+`<div class="cl-rules"><b>What a ${escape(c.market)} label needs</b><ul>${m.rules.map(r=>`<li>${escape(r)}</li>`).join('')}</ul>${m.links.map(([t,u])=>`<a href="${u}" target="_blank" rel="noopener">${escape(t)} ↗</a>`).join('<br>')}<p class="note">A summary to guide your research, reviewed November 2026; it is not legal advice. Confirm the current rules with your importer or a compliance specialist.</p></div>`)
 +srcLink('care','care label','srcSync')+panel('Composition & identification',fields(f('care','brand','Brand')+f('care','size','Size')+f('care','origin','Country of manufacture')+f('care','contact','Responsible business / address')+(m.fields.includes('rn')?f('care','rn',c.market==='Canada'?'CA identification number':'RN number (or company name)'):'')+(m.fields.includes('mfgDate')?f('care','mfgDate','Month and year of manufacture'):'')+(m.fields.includes('mrp')?f('care','mrp','MRP incl. all taxes (₹)','number'):'')+f('care','shell','Shell composition — percentage and generic fibre per line','textarea')+f('care','lining','Lining composition — leave blank if absent','textarea'))+actionBar(button('careFromPack','Use tech pack details'))+note('Each component must total 100%. Example: “95 Cotton” and “5 Elastane” on separate lines. Fibre names are translated for the languages you tick; check them against the destination’s official list.'))
 +panel('Approved care instructions',fields(Object.keys(careOptions).map(k=>f('care',k,k[0].toUpperCase()+k.slice(1),'text',careOptions[k])).join('')+f('care','evidence','Care test / supplier approval reference')+f('care','extra','Additional approved wording','textarea'))+note('Select instructions from testing of the finished garment and all trims. Composition alone cannot establish safe care.'))
 +panel('Live label',fields(f('care','material','Label material','text',LABEL_MATS.map(x=>x[0]))+f('care','labelColour','Label colour','text',['White','Ivory','Black','Navy'])+f('care','width','Label width (mm)','number')+f('care','height','Label height (mm)','number')+f('care','fold','Fold / finish','text',['End fold','Centre fold','Straight cut'])+f('care','symbols','Show care symbols','checkbox')+f('care','logo','Brand name as a heading','checkbox'))+careLabelHTML()+(c.symbols?note('Symbols are drawn in the common ISO 3758 / ASTM D5489 style. In many countries the ISO symbols are registered trademarks of GINETEX; check licensing for your market.'):'')+actionBar(button('labelSVG','Download label SVG',true)+button('labelTXT','Download label text')+button('print','Print label sheet'))+`<a class="button" href="export-market-checker">Check destination requirements →</a>`);}
const views={'trend-to-style':briefView,'size-chart-builder':sizeView,'tech-pack-builder':packView,'fabric-finder':fabricView,'export-market-checker':marketView,'product-description-writer':copyView,'decoration-cost-estimator':decorationView,'care-label-generator':careView};
function render(){try{$('#app').innerHTML=views[tool]();}catch(e){$('#app').innerHTML=`<p class="error">${escape(e.message)}</p>`;}if(tool==='care-label-generator')setTimeout(paintLabels,0);}
function refreshResults(el){try{const tmp=document.createElement('div');tmp.innerHTML=views[tool]();const old=[...$('#app').children],next=[...tmp.children];for(let i=0;i<old.length;i++)if(next[i]&&!old[i].contains(el))old[i].replaceWith(next[i]);document.querySelectorAll('[data-bom-line]').forEach(node=>{const row=state.pack.bom[Number(node.dataset.bomLine)];if(row)node.textContent=money(row.quantity*row.price);});const total=$('#bomTotal');if(total)total.textContent='BOM per garment: '+money(state.pack.bom.reduce((sum,r)=>sum+r.quantity*r.price,0));}catch(e){$('#status').textContent=e.message;}}
function sizeCSV(){const d=sizeData(),s=state.size;return [['Collection',state.name],['Style code',s.styleCode],['Style name',s.styleName],['Season',s.season],['Category',s.category],['Garment',s.garment],['Fit',s.fit],['Fabric',s.fabricType],['Sleeve',s.sleeve],['Neck / collar',s.collar],['Measurement basis',s.mode],['Market / size system',s.market],['Unit',s.unit],['Base size',s.base],[],['Code','Point of measure','How to measure',...d.labels,'Tolerance ±','Grade −','Grade +'],...d.rows.map((r,i)=>[s.rows[i].code||'',r.name,s.rows[i].how||'',...r.values,r.tolerance,s.rows[i].down,s.rows[i].up])];}
