$('#app').addEventListener('input',e=>{const el=e.target;if(el.dataset.dec!==undefined&&['text','number'].includes(el.type)){try{decSet(el);save();refreshResults(el);}catch(err){$('#status').textContent=err.message;}return;}if(!['text','number','textarea'].includes(el.type))return;if(el.dataset.sv!==undefined){try{const r=state.size.rows[+el.dataset.sv],z=el.dataset.size,v=S.number(el.value,'Measurement');if(z===state.size.base){r.base=v;if(r.vals)delete r.vals[z];}else{r.vals=r.vals||{};r.vals[z]=v;el.parentNode.classList.add('own');}save();syncSpec();refreshResults(el);}catch(err){$('#status').textContent=err.message;}return;}if(el.dataset.row==='size'&&['down','up','base'].includes(el.dataset.key)){const r=state.size.rows[+el.dataset.index];if(r&&r.vals){delete r.vals;}}try{const value=el.type==='number'?S.number(el.value,el.dataset.key):el.value;if(el.dataset.row){const arrays={size:state.size.rows,bom:state.pack.bom,callout:state.pack.callouts,piece:state.pack.pieces,gallery:state.pack.gallery,qc:state.pack.qc};arrays[el.dataset.row][Number(el.dataset.index)][el.dataset.key]=value;}else if(el.dataset.group){state[el.dataset.group][el.dataset.key]=value;if(el.dataset.group==='copy')state.copy.result='';}save();syncSpec();updateCare();}catch(err){$('#status').textContent=err.message;}});
$('#app').addEventListener('change',async e=>{const el=e.target;try{if(el.dataset.sv!==undefined)return;if(el.dataset.dec!==undefined){decSet(el);save();render();return;}if(el.dataset.carelang!==undefined){const L=new Set(careLangs());if(el.checked)L.add(el.dataset.carelang);else L.delete(el.dataset.carelang);if(!L.size)L.add('en');state.care.langs=[...L].join(',');save();updateCare();return;}if(el.dataset.group==='care'&&el.dataset.key==='market'){state.care.market=el.value;state.care.langs='';save();render();return;}if(el.dataset.decimg!==undefined){const file=el.files[0];if(!file)return;const a=await shrinkArt(file),it=decItems()[+el.dataset.decimg];it.img=a.data;it.h=+(it.w*a.ratio).toFixed(1);if(JSON.stringify(state).length>4000000){it.img='';throw Error('This image would exceed the browser storage limit. Remove other images first.');}save();render();return;}if(el.dataset.sizerange!==undefined){const r=SZ.ranges[+el.value];if(r){state.size.labels=r[1];state.size.base=r[2];save();render();}return;}if(el.dataset.import==='size'){const file=el.files[0];if(!file)return;$('#status').textContent='Reading '+file.name+'…';await importSize(file);save();render();$('#status').textContent=state.size.source;return;}if(el.dataset.group==='size'&&['labels','unit'].includes(el.dataset.key)){state.size[el.dataset.key]=el.value;save();render();return;}if(el.dataset.import==='copybatch'){const file=el.files[0];if(!file)return;try{runBatch(await file.text());}catch(e){$('#status').textContent=e.message;}render();return;}if(el.dataset.import==='pack'){const file=el.files[0];if(!file)return;$('#status').textContent='Reading '+file.name+'…';state.pack.source=await importPack(file);save();render();$('#status').textContent=state.pack.source;return;}if(el.dataset.gallery!==undefined){for(const file of [...el.files].slice(0,16-state.pack.gallery.length)){const a=await shrinkArt(file,1000);append(state.pack.gallery,{img:a.data,name:file.name.replace(/\.[a-z0-9]+$/i,'').replace(/[-_]+/g,' ').slice(0,120),section:'Construction'},16);}if(JSON.stringify(state).length>4000000){state.pack.gallery.pop();throw Error('Browser storage is nearly full. Remove some images first.');}save();render();return;}if(el.dataset.sketch){const file=el.files[0];if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>15000000)throw Error('Use a PNG, JPEG or WebP image.');const data=file.size>900000?await new Promise((ok,no)=>{const u=URL.createObjectURL(file),im=new Image();im.onload=()=>{const sc=Math.min(1,1600/Math.max(im.naturalWidth,im.naturalHeight)),c=document.createElement('canvas');c.width=Math.round(im.naturalWidth*sc);c.height=Math.round(im.naturalHeight*sc);c.getContext('2d').drawImage(im,0,0,c.width,c.height);URL.revokeObjectURL(u);ok(c.toDataURL('image/jpeg',.85));};im.onerror=()=>no(Error('That image could not be read.'));im.src=u;}):await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file);});if(JSON.stringify({...state,pack:{...state.pack,images:{...state.pack.images,[el.dataset.sketch]:data}}}).length>4000000)throw Error('This image would exceed the studio backup limit. Export and remove older snapshots, or use a smaller image.');state.pack.images[el.dataset.sketch]=data;}else if(el.dataset.check!==undefined){state.market.checks[state.market.country+':'+state.market.product+':'+el.dataset.check]=el.checked;save();render();return;}else if(el.dataset.row){const arrays={size:state.size.rows,bom:state.pack.bom,callout:state.pack.callouts,piece:state.pack.pieces,gallery:state.pack.gallery,qc:state.pack.qc};const value=el.type==='number'?S.number(el.value,el.dataset.key):el.value;arrays[el.dataset.row][Number(el.dataset.index)][el.dataset.key]=value;}else if(el.dataset.group){let value=el.type==='checkbox'?el.checked:el.type==='number'?S.number(el.value,el.dataset.key):el.value;state[el.dataset.group][el.dataset.key]=value;if(el.dataset.group==='copy')state.copy.result='';}save();if(el.dataset.sketch||el.dataset.group==='decoration'&&['method','actual'].includes(el.dataset.key))render();else{refreshResults(el);updateCare();}}catch(err){$('#status').textContent=err.message;}});
$('#app').addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;try{const ret=actions[b.dataset.action]?.(b);if(ret&&ret.then)ret.catch(err=>{$('#status').textContent=err.message;});save();render();if(['chooseFabric','decorationBom'].includes(b.dataset.action))$('#status').textContent='Added to the Tech Pack Builder bill of materials. Review quantity, supplier and rates there.';}catch(err){$('#status').textContent=err.message;}});
$('#collectionName').value=state.name;$('#collectionName').addEventListener('change',e=>{state.name=e.target.value.slice(0,100);save();});$('#backup').onclick=()=>download('forecut-production-studio.json',JSON.stringify(state,null,2),'application/json');$('#restore').onclick=()=>$('#restoreFile').click();$('#restoreFile').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>4000000)throw Error('Studio backup exceeds 4 MB.');const next=valid(JSON.parse(await file.text()));state=next;blocked=false;save();$('#collectionName').value=state.name;render();}catch(err){$('#status').textContent=err.message;}e.target.value='';};$('#print').onclick=()=>window.print();
